// @sourcefile .\Sound\SoundHdr.cpp
void __fastcall SOUNDHDR_LoadSoundFile(int32_t nSoundId, int32_t bForceSync, int32_t bRespectRecency) {
    void* pSoundData;
    D2SoundsTxt* pSound;
    char szPath[80];
    D2MPQFileStrc* pMpqFile;
    int32_t* pSoundDataBytes;
    char* szSourceFile;
    if (!pTxtSounds || nSoundId < 0 || nSoundId >= nTxtSoundsSize) {
      pSound = 0;
    } else {
      pSound = pTxtSounds + nSoundId;
    }

    int nNowVolume = gnCurrentGameAudioVolume;
    if (pSound->bFileNotFound) {
      return;
    }

    int nLoadStateOrBytes = pSound->nLoadState;
    if (nLoadStateOrBytes == 2) {
      return;
    }

    int32_t bForceSyncLocal = bForceSync;
    if (nLoadStateOrBytes == 1) {
      if (!bForceSync) {
        return;
      }
      if (true && bForceSync) {
        SOUNDHDR_CompleteAsyncLoad(pSound);
        return;
      }
    }
    if (nLoadStateOrBytes) {
      return;
    }

    SOUNDHDR_BuildSoundPath(nSoundId, szPath);
    int32_t nResult = Fog::Source::SFile::ARCHIVE_OpenD2FileWrap(szPath, &pMpqFile);
    if (!nResult) {
      pSound->bFileNotFound = 1;
      return;
    }

    DWORD nFileSize = Fog::Source::SFile::ERRORMANAGER_FGetFileSize(pMpqFile, (LPDWORD)0x0);
    Fog::Source::SFile::ERRORMANAGER_FCloseFile(pMpqFile);
    if (gnSoundBufferBytesLoaded + nFileSize > gnSoundBufferMaxBytes) {
      BOOL BVar1;
      BVar1 = SOUNDHDR_EvictLeastRecentlyUsed(gnSoundBufferBytesLoaded - gnSoundBufferMaxBytes + nFileSize, bForceSyncLocal, bRespectRecency);
      if (!BVar1) {
        gnSoundEvictedAudioVolume = nNowVolume;
        return;
      }
    }
    if (bForceSyncLocal) {
      nResult = 0x301;
      szSourceFile = ".\\Sound\\SoundHdr.cpp";
      pSoundDataBytes = &pSound->nSoundDataBytes;
      pSoundData = D2Hell::D2FILE_AllocAndLoadD2File(D2Win::Src::D2WinArchive::ReturnZero(), szPath, (uint32_t*)pSoundDataBytes, szSourceFile, nResult);
      pSound->pSoundDataBuffer = pSoundData;
      if (pSoundData) {
        nLoadStateOrBytes = pSound->nSoundDataBytes;
        if (nLoadStateOrBytes) {
          gnSoundBufferBytesLoaded += nLoadStateOrBytes;
          SOUNDHDR_UpdateLRUTimestamp(nSoundId);
          pSound->nLoadState = 2;
          GAME::Sound::SOUND_ParseStreamWavHeader(pSound);
          return;
        }
      }

      Fog::Src::ErrorManager::ERROR_UnrecoverableInternalError_Halt("", Fog::Src::ErrorManager::GetInstructionPointer(), 0x302);
      exit(-1);
    }

    D2AsyncData_Line0x128* pAsyncData = Fog::Src::AsyncData::STRUCT_AllocAsyncData_Line0x128(nullptr, szPath, 1, 0, -1, nullptr, nullptr, -2, ".\\Sound\\SoundHdr.cpp", 0x31b);
    pSound->pAsyncData = pAsyncData;
    if (!pAsyncData) {
      return;
    }

    size_t nReadSize = Fog::Src::AsyncData::ASYNCDATA_GetReadSize(pAsyncData);
    gnSoundBufferBytesLoaded += nReadSize;
    pSound->nSoundDataBytes = nReadSize;
    SOUNDHDR_UpdateLRUTimestamp(nSoundId);
    gnSoundAsyncLoadCount++;
    pSound->nLoadState = 1;
}

void __fastcall SOUNDHDR_ProcessAsyncLoads(int32_t dwTick) {
    if (pTxtSounds) {
      BOOL bForce = !dwTick;
      if (!dwTick || (uint32_t)(dwTick - gdwLastSoundAsyncLoadTick) >= 0x19) {
        for (int nRowIndex = 1; nRowIndex <= 2933; nRowIndex++) {
          D2SoundsTxt* pSoundRow = &pTxtSounds[nRowIndex];
          if (!pSoundRow->nLoadState && (pSoundRow->nRefCount || pSoundRow->Cache)) {
            if (bForce || gnSoundAsyncLoadCount < 0xf && (uint32_t)(dwTick - gnSoundEvictedAudioVolume) >= 0xfa) {
              SOUNDHDR_LoadSoundFile(nRowIndex, bForce, 1);
            } else {
              continue;
            }
          }
          if (pSoundRow->nLoadState == 1 && Fog::Src::AsyncData::ASYNCDATA_IsComplete((D2AsyncData_Line0x128*)pSoundRow->pAsyncData)) {
            SOUNDHDR_CompleteAsyncLoad(pSoundRow);
          }
        }
        gdwLastSoundAsyncLoadTick = dwTick;
      }
    }
}

void __stdcall DRAW_AfterDraw() {
    BOOL bSoundInitialized = GAME::Sound::SOUND_IsInitialized();
    if (!bSoundInitialized) {
      return;
    }

    SOUND_UpdateEnvironmentAmbience(gnCurrentGameAudioVolume);
    GAME::Wall2::WALL2_UpdateAmbientMusic(gnCurrentGameAudioVolume);
    SOUNDHDR_ProcessAsyncLoads(gnCurrentGameAudioVolume);
    SOUND_UpdateAllChannels(gnCurrentGameAudioVolume);
    GAME::Sound::SOUND_UpdateNonLoopingStreams();
    gnCurrentGameAudioVolume++;
    /* DWORD dwMilliseconds for Sleep */ Sleep(0);
}

void __fastcall SOUNDHDR_UpdateRegistryVersion(int32_t nSoundHeaderIndex) {
    uint8_t byRequiredVersionFlag;
    uint8_t byCurrentVersionFlag;
    char szVersionString[100];
    int nVersionMinor;
    int nVersionRevision;
    int dwRequiredVersion = gdwSoundHeaderCacheIndex[nSoundHeaderIndex].nCutsceneId;
    uint32_t dwVersionBuild = 0x22;
    int32_t bReadOk = Storm::Source::SReg::SRegLoadString("Diablo II", "Aux Battle.net", 0, szVersionString, 100);
    if (bReadOk) {
      int nVersionMajor;
      sscanf(szVersionString, "%d.%d.%d.%d", &nVersionMajor, &nVersionMinor, &nVersionRevision, (int*)&dwVersionBuild);
      if (dwVersionBuild & 1) {
        byCurrentVersionFlag = 7;
      } else {
        if (dwVersionBuild & 0x80) {
          byCurrentVersionFlag = 6;
        } else if (dwVersionBuild & 0x10) {
          byCurrentVersionFlag = 5;
        } else {
          if (dwVersionBuild & 8) {
            byCurrentVersionFlag = 4;
          } else {
            if (dwVersionBuild & 0x40) {
              byCurrentVersionFlag = 3;
            } else {
              byCurrentVersionFlag = (dwVersionBuild & 4) != 0 ? 2 : 1;
            }
          }
        }
      }
    } else {
      byCurrentVersionFlag = 0x22;
    }

    switch (dwRequiredVersion) {
      case 2:
        byRequiredVersionFlag = 2;
      break;
      case 3:
        byRequiredVersionFlag = 3;
      break;
      case 4:
        byRequiredVersionFlag = 4;
      break;
      case 5:

      case 6:
        byRequiredVersionFlag = 5;
      break;
      case 7:
        byRequiredVersionFlag = 7;
      break;
      default:
        byRequiredVersionFlag = 1;
    }

    if (byRequiredVersionFlag <= byCurrentVersionFlag) {
      return;
    }

    switch (byRequiredVersionFlag) {
      case 7:
        dwVersionBuild = 0x23;
      break;
      case 5:
        dwVersionBuild = 0xb2;
      break;
      case 4:
        dwVersionBuild = 0x2a;
      break;
      case 3:
        dwVersionBuild = 0x62;
      break;
      case 2:
        dwVersionBuild = 0x26;
      break;
      default:
        dwVersionBuild = 0x22;
      break;
    }

    sprintf(szVersionString, "%d.%d.%d.%d", 0xd8, 0x94, 0xf6, dwVersionBuild);
    Storm::Source::SReg::SRegSaveString("Diablo II", "Aux Battle.net", 0, szVersionString);
}

